#!/usr/bin/env node
/**
 * Generates utils/generatedConfig.js from build-time environment variables.
 *
 * Run automatically by `npm run build` (prebuild) and `npm run preview`.
 * Direct `zeus build` calls use the last generated file.
 *
 * Resolution order for RESOLVE_BASE_URL:
 *   1. process.env.RESOLVE_BASE_URL          (CI / shell environment)
 *   2. RESOLVE_BASE_URL from ./.env          (local file, same file zeus reads)
 *   3. DEFAULT_RESOLVE_BASE_URL below       (fallback)
 */
import fs from 'node:fs'
import path from 'node:path'

const DEFAULT_RESOLVE_BASE_URL = 'https://web-amcereijos-projects.vercel.app'

// npm runs scripts with the package root as cwd (zepp_app/).
const ROOT = process.cwd()
const OUT_FILE = path.join(ROOT, 'utils', 'generatedConfig.js')
const ENV_FILE = path.join(ROOT, '.env')

function readEnvFile(file) {
  try {
    const out = {}
    for (const rawLine of fs.readFileSync(file, 'utf8').split('\n')) {
      const line = rawLine.trim()
      if (!line || line.startsWith('#')) continue
      const eq = line.indexOf('=')
      if (eq <= 0) continue
      const key = line.slice(0, eq).trim()
      let value = line.slice(eq + 1).trim()
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1)
      }
      out[key] = value
    }
    return out
  } catch (e) {
    return {}
  }
}

function normalizeUrl(url) {
  return url.replace(/\/+$/, '')
}

function main() {
  const fromFile = readEnvFile(ENV_FILE)
  const raw =
    process.env.RESOLVE_BASE_URL ||
    fromFile.RESOLVE_BASE_URL ||
    DEFAULT_RESOLVE_BASE_URL
  const source = process.env.RESOLVE_BASE_URL
    ? 'environment'
    : fromFile.RESOLVE_BASE_URL
      ? '.env'
      : 'default'

  const url = normalizeUrl(raw.trim())

  if (!/^https?:\/\/[^\s]+$/.test(url)) {
    console.error(
      `[write-config] Invalid RESOLVE_BASE_URL: "${url}" (expected an http(s) URL)`
    )
    process.exit(1)
  }

  const contents = `// AUTO-GENERATED by scripts/write-config.js — do not edit by hand.
// Source: ${source}
export const RESOLVE_BASE_URL = '${url}'
`

  const previous = fs.existsSync(OUT_FILE) ? fs.readFileSync(OUT_FILE, 'utf8') : null
  if (previous !== contents) {
    fs.writeFileSync(OUT_FILE, contents)
    console.log(`[write-config] RESOLVE_BASE_URL = ${url} (from ${source})`)
  } else {
    console.log(`[write-config] RESOLVE_BASE_URL = ${url} (from ${source}, unchanged)`)
  }
}

main()
